sys_script_include.script:
var GeneratePDFScoped = Class.create();
GeneratePDFScoped.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    createPDF: function() {
        // gs.info("== createPDF 被调用 ==");
        // gs.info("createPDF GeneratePDFScoped=========================");
        var sysId = this.getParameter('sysparm_sys_id');
        // gs.info("sysId sysId=========================" + sysId);
        var item = new GlideRecordSecure('x_1639325_mydemo_mydemo');
        if (!item.get(sysId)) return '';

        // gs.info("html=========================");
        var html = "<html><body>";
        html += "<h1>请求详情</h1>";
        html += "<p><strong>编号:</strong> " + item.number + "</p>";
        html += "<p><strong>描述:</strong> " + item.short_description + "</p>";
        html += "</body></html>";
        var v = new sn_pdfgeneratorutils.PDFGenerationAPI;
        var result = v.convertToPDF(html, "x_1639325_mydemo_mydemo", sysId, "myPDF");
        // gs.info(JSON.stringify(result));
        // gs.info("htmleeeeeeee=========================");
        // var pdf = new GlidePDFGenerator();
        // gs.info("GlidePDFGenerator=========================");
        // pdf.setHTML(html);
        // var fileName = item.number + "_Summary.pdf";
        // var pdfSysId = pdf.saveAttachment("x_1639325_mydemo_mydemo", sysId, fileName);

        // var file = new GlideSysAttachment().getAttachmentRecordBySysId(pdfSysId);
        // return file ? "/sys_attachment.do?sys_id=" + pdfSysId : '';

		return JSON.stringify(result);


    },
    type: 'GeneratePDFScoped'
});
